################################################################################
## Form generated by hand to match the Designer-output pattern (no .ui file).
##
## 计划排布 Tab 的纯布局代码 —— 与 excel_merge 的
## generated/ui_excel_merge_dialog.py 风格一致:一个 Ui_* 类,
## setupUi(self, Widget) 构建控件树。
## 业务逻辑(信号连接/生成/结果展示)留在 dialogs/plan_schedule_tab.py。
##
## WARNING! 若日后用 Qt Designer 重新生成,本文件会被覆盖。
##
## 本文件无 .ui 源、不走 pyside6-uic 再生(手维护,与 ui_excel_merge_dialog.py 同款)。
################################################################################

from PySide6.QtWidgets import (
    QComboBox,
    QHBoxLayout,
    QHeaderView,
    QLabel,
    QLineEdit,
    QPushButton,
    QSpinBox,
    QTableWidget,
    QVBoxLayout,
    QWidget,
)

# 结果表格列头(与解析结果字段一一对应;放此处供 setupUi 与测试共用)
HEADERS = ["项点", "开始", "结束", "天数", "状态"]

# 年份选择范围(日期串缺年份时补全用)
YEAR_MIN = 2000
YEAR_MAX = 2100

# 日期格内容下拉框文案(索引 -> 常量值的映射见 controllers/plan_schedule_controller.py)
CELL_LABELS = ["第几天(1,2,3…)", "项点名称(第x列/批次)"]


class Ui_PlanScheduleDialog:
    """计划排布 Tab 的 UI 构建器(setupUi 模式,与其他 Tab 一致)。"""

    def setupUi(self, PlanScheduleDialog: QWidget) -> None:
        if not PlanScheduleDialog.objectName():
            PlanScheduleDialog.setObjectName("PlanScheduleDialog")

        layout = QVBoxLayout(PlanScheduleDialog)
        layout.setObjectName("verticalLayout_main")

        # ---- 输入文件行 ----
        input_row = QHBoxLayout()
        input_row.setObjectName("horizontalLayout_input")

        input_row.addWidget(QLabel("项点清单:", PlanScheduleDialog))

        self.edit_input = QLineEdit(PlanScheduleDialog)
        self.edit_input.setObjectName("edit_input")
        self.edit_input.setPlaceholderText("选择清单 Excel:项点名称 / 起始日期 / 终止日期")
        input_row.addWidget(self.edit_input)

        self.btn_browse_input = QPushButton("选择", PlanScheduleDialog)
        self.btn_browse_input.setObjectName("btn_browse_input")
        input_row.addWidget(self.btn_browse_input)

        self.btn_template = QPushButton("导出模板", PlanScheduleDialog)
        self.btn_template.setObjectName("btn_template")
        input_row.addWidget(self.btn_template)

        layout.addLayout(input_row)

        # ---- 输出目录 + 年份行 ----
        out_row = QHBoxLayout()
        out_row.setObjectName("horizontalLayout_output")

        out_row.addWidget(QLabel("输出目录:", PlanScheduleDialog))

        self.edit_outdir = QLineEdit(PlanScheduleDialog)
        self.edit_outdir.setObjectName("edit_outdir")
        self.edit_outdir.setPlaceholderText("选择或输入输出目录(默认跟随上次或清单所在目录)")
        out_row.addWidget(self.edit_outdir)

        self.btn_browse = QPushButton("浏览", PlanScheduleDialog)
        self.btn_browse.setObjectName("btn_browse")
        out_row.addWidget(self.btn_browse)

        out_row.addWidget(QLabel("缺省年份:", PlanScheduleDialog))

        self.spin_year = QSpinBox(PlanScheduleDialog)
        self.spin_year.setObjectName("spin_year")
        self.spin_year.setRange(YEAR_MIN, YEAR_MAX)  # 默认值由 Tab 构造时设为当前年份
        out_row.addWidget(self.spin_year)

        out_row.addWidget(QLabel("格子内容:", PlanScheduleDialog))

        self.cmb_cell = QComboBox(PlanScheduleDialog)
        self.cmb_cell.setObjectName("cmb_cell")
        self.cmb_cell.addItems(CELL_LABELS)
        self.cmb_cell.setCurrentIndex(0)
        out_row.addWidget(self.cmb_cell)

        layout.addLayout(out_row)

        # ---- 操作按钮行 ----
        btn_row = QHBoxLayout()
        btn_row.setObjectName("horizontalLayout_buttons")

        self.btn_generate = QPushButton("生成计划排布", PlanScheduleDialog)
        self.btn_generate.setObjectName("btn_generate")
        btn_row.addWidget(self.btn_generate)

        btn_row.addStretch(1)

        self.lbl_status = QLabel("就绪", PlanScheduleDialog)
        self.lbl_status.setObjectName("lbl_status")
        btn_row.addWidget(self.lbl_status)

        layout.addLayout(btn_row)

        # ---- 结果表格 ----
        self.table = QTableWidget(0, len(HEADERS), PlanScheduleDialog)
        self.table.setObjectName("table")
        self.table.setHorizontalHeaderLabels(HEADERS)
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch)
        layout.addWidget(self.table, stretch=1)
